"""Media bundle routing and reference-image composition nodes."""

from __future__ import annotations

import asyncio
import hashlib
import json
import math
import os
import shutil
import threading
import time
from collections.abc import Mapping
from dataclasses import dataclass
from fractions import Fraction
from typing import Any

import torch
from PIL import Image, ImageColor

from ..core.video_api import make_video_components


MEDIA_BUNDLE_TYPE = "MINIMAX_H3_MEDIA_BUNDLE"
MEDIA_LOADER_TYPE = "WyslMediaLoader"
MEDIA_LOADER_IMAGE_EXTENSIONS = {
    ".png", ".jpg", ".jpeg", ".webp", ".bmp", ".gif", ".tif", ".tiff", ".avif", ".heic",
}
MEDIA_LOADER_AUDIO_EXTENSIONS = {
    ".wav", ".mp3", ".flac", ".ogg", ".oga", ".m4a", ".aac", ".opus", ".wma",
}
MEDIA_LOADER_VIDEO_EXTENSIONS = {
    ".mp4", ".webm", ".mov", ".mkv", ".avi", ".m4v", ".mpeg", ".mpg", ".wmv", ".flv",
}
MEDIA_LOADER_EXTENSIONS = {
    "image": MEDIA_LOADER_IMAGE_EXTENSIONS,
    "audio": MEDIA_LOADER_AUDIO_EXTENSIONS,
    "video": MEDIA_LOADER_VIDEO_EXTENSIONS,
}
# Browsers cannot decode TIFF/HEIC/AVIF and cannot show a first frame for a
# video element without a poster, so the node asks the backend to render small
# webp thumbnails instead of leaving a broken or blank tile in the panel.
MEDIA_LOADER_THUMBNAIL_SIZES = (128, 384)
MEDIA_LOADER_THUMBNAIL_MAX_PIXELS = 64_000_000
MEDIA_LOADER_THUMBNAIL_DIR = "wysl_thumbs"
MEDIA_LOADER_THUMBNAIL_TTL = 12 * 60 * 60
MEDIA_LOADER_THUMBNAIL_MIN_FREE_BYTES = 512 * 1024 * 1024
MEDIA_LOADER_THUMBNAIL_PRUNE_INTERVAL = 600.0
_MEDIA_LOADER_THUMBNAIL_CACHE: dict[tuple[str, int], str] = {}
_MEDIA_LOADER_THUMBNAIL_LOCKS: dict[str, Any] = {}
_MEDIA_LOADER_THUMBNAIL_REGISTRY_LOCK = threading.Lock()
_MEDIA_LOADER_THUMBNAIL_LAST_PRUNE = 0.0
_MEDIA_LOADER_THUMBNAIL_EXECUTOR: Any = None


@dataclass(frozen=True)
class WyslMediaInput:
    """One item in the bundle contract used by the upstream H3 loader."""

    input_index: int
    media_type: str
    value: Any


@dataclass(frozen=True)
class WyslMediaBundle:
    """Duck-typed equivalent of MiniMax H3's MINIMAX_H3_MEDIA_BUNDLE."""

    items: tuple[WyslMediaInput, ...]


def _execution_blocker() -> Any:
    """Return ComfyUI's blocker without making tests import the full runtime."""
    try:
        from comfy_execution.graph import ExecutionBlocker
    except Exception:
        return None
    return ExecutionBlocker(None)


def _media_loader_kind(filename: str) -> str | None:
    suffix = os.path.splitext(str(filename or ""))[1].lower()
    for kind, extensions in MEDIA_LOADER_EXTENSIONS.items():
        if suffix in extensions:
            return kind
    return None


def _media_loader_normalize_filename(value: Any) -> str:
    """Return an input-relative path, rejecting traversal and absolute paths."""
    filename = str(value or "").strip().replace("\\", "/").lstrip("/")
    if not filename or "\x00" in filename or os.path.isabs(filename):
        return ""
    parts = [part for part in filename.split("/") if part and part != "."]
    if not parts or any(part == ".." for part in parts):
        return ""
    return "/".join(parts)


def _media_loader_normalize_state(value: Any) -> dict[str, list[str]]:
    """Parse the UI state without ever accepting arbitrary filesystem paths."""
    result = {"images": [], "audios": [], "videos": []}
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except (TypeError, ValueError):
            value = {}
    if not isinstance(value, Mapping):
        return result
    for kind in ("image", "audio", "video"):
        key = f"{kind}s"
        entries = value.get(key)
        if not isinstance(entries, (list, tuple)):
            continue
        seen: set[str] = set()
        for entry in entries:
            raw = entry.get("filename") if isinstance(entry, Mapping) else entry
            filename = _media_loader_normalize_filename(raw)
            if not filename or filename in seen:
                continue
            # The state is allowed to retain a file only in its matching type
            # list. This prevents a malformed workflow from mixing outputs.
            if _media_loader_kind(filename) != kind:
                continue
            seen.add(filename)
            result[key].append(filename)
    return result


def _media_loader_input_path(filename: str) -> str:
    try:
        import folder_paths

        root = os.path.realpath(str(folder_paths.get_input_directory()))
        candidate = os.path.realpath(os.path.join(root, filename.replace("/", os.sep)))
        if os.path.commonpath((root, candidate)) != root:
            raise ValueError("媒体文件必须位于 ComfyUI/input 目录内")
        if not os.path.isfile(candidate):
            raise ValueError(f"找不到 input 媒体文件: {filename}")
        return candidate
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError(f"无法访问 input 媒体文件: {filename}") from exc


def _media_loader_load_audio(path: str) -> dict[str, Any]:
    try:
        from comfy_extras import nodes_audio

        waveform, sample_rate = nodes_audio.load(path)
    except Exception as exc:
        raise ValueError(f"无法读取音频文件 {os.path.basename(path)!r}: {exc}") from exc
    if not isinstance(waveform, torch.Tensor) or waveform.ndim not in {2, 3}:
        raise ValueError(f"音频文件 {os.path.basename(path)!r} 没有可用采样数据")
    if waveform.ndim == 2:
        waveform = waveform.unsqueeze(0)
    return {
        "waveform": waveform.to(device="cpu", dtype=torch.float32).contiguous(),
        "sample_rate": int(sample_rate),
    }


def _media_loader_load_video(path: str) -> dict[str, Any]:
    try:
        from comfy_api.latest import InputImpl

        components = InputImpl.VideoFromFile(path).get_components()
    except Exception as exc:
        raise ValueError(f"无法读取视频文件 {os.path.basename(path)!r}: {exc}") from exc
    frames = components.images
    if not isinstance(frames, torch.Tensor) or frames.ndim != 4 or frames.shape[0] < 1:
        raise ValueError(f"视频文件 {os.path.basename(path)!r} 没有可用帧")
    frames = frames.detach().to(device="cpu").contiguous()
    audio = components.audio
    audio_payload = None
    waveform = audio.get("waveform") if isinstance(audio, Mapping) else None
    if isinstance(waveform, torch.Tensor):
        audio_payload = {
            "waveform": waveform.detach().to(device="cpu").contiguous(),
            "sample_rate": int(audio.get("sample_rate") or 48_000),
        }
    return {
        "images": frames,
        "audio": audio_payload,
        "fps": float(components.frame_rate or 24.0),
    }


def _media_loader_load_image(filename: str) -> torch.Tensor:
    try:
        import nodes

        return nodes.LoadImage().load_image(filename)[0]
    except Exception as exc:
        raise ValueError(f"无法读取图片文件 {os.path.basename(filename)!r}: {exc}") from exc


def _media_loader_list_folder(folder: str) -> tuple[str, list[dict[str, str]], list[dict[str, str]]]:
    """List only the selected input folder; never recursively enumerate files."""
    import folder_paths

    root = os.path.realpath(str(folder_paths.get_input_directory()))
    normalized = _media_loader_normalize_filename(folder).rstrip("/")
    folder_path = os.path.realpath(os.path.join(root, normalized.replace("/", os.sep)))
    if os.path.commonpath((root, folder_path)) != root or not os.path.isdir(folder_path):
        raise ValueError("选择的文件夹不在 ComfyUI/input 目录内")

    directories: list[dict[str, str]] = []
    files: list[dict[str, str]] = []
    for entry in sorted(os.scandir(folder_path), key=lambda item: (not item.is_dir(), item.name.casefold())):
        relative = "/".join(part for part in (normalized, entry.name) if part)
        if entry.is_dir():
            directories.append({"name": entry.name, "path": relative})
            continue
        kind = _media_loader_kind(entry.name)
        if kind:
            try:
                size = entry.stat().st_size
            except OSError:
                size = 0
            files.append({"name": entry.name, "path": relative, "type": kind, "size": size})
    parent = "/".join(normalized.split("/")[:-1]) if normalized else ""
    return normalized, directories, files


def _media_loader_thumbnail_executor() -> Any:
    """Decode thumbnails on a small dedicated pool.

    Video decoding is CPU heavy, so it must neither block the server event loop
    nor occupy every worker of the shared default executor while a user browses
    a folder full of clips.
    """
    global _MEDIA_LOADER_THUMBNAIL_EXECUTOR

    executor = _MEDIA_LOADER_THUMBNAIL_EXECUTOR
    if executor is not None:
        return executor
    with _MEDIA_LOADER_THUMBNAIL_REGISTRY_LOCK:
        if _MEDIA_LOADER_THUMBNAIL_EXECUTOR is None:
            from concurrent.futures import ThreadPoolExecutor

            _MEDIA_LOADER_THUMBNAIL_EXECUTOR = ThreadPoolExecutor(
                max_workers=2,
                thread_name_prefix="wysl-thumb",
            )
        return _MEDIA_LOADER_THUMBNAIL_EXECUTOR


def _media_loader_thumbnail_cache_dir() -> str:
    """Return a cache root that survives restarts and stays out of the input tree.

    ComfyUI's own temp folder is wiped between runs, which would make the first
    panel open after every restart re-decode every selected file. The system
    temp directory keeps the cache warm between runs and never writes inside the
    browsed `input` tree.
    """
    import tempfile

    root = tempfile.gettempdir() or os.getcwd()
    cache_dir = os.path.join(os.path.realpath(str(root)), MEDIA_LOADER_THUMBNAIL_DIR)
    # OSError here is a server-side problem, not a bad filename, so it reaches
    # the route's 500 branch instead of being reported as a missing file.
    os.makedirs(cache_dir, exist_ok=True)
    return cache_dir


def _media_loader_thumbnail_max_edge(size: Any) -> int:
    """Snap an arbitrary request to a published tier so the cache stays bounded."""
    try:
        requested = int(size)
    except (TypeError, ValueError):
        requested = MEDIA_LOADER_THUMBNAIL_SIZES[0]
    return min(MEDIA_LOADER_THUMBNAIL_SIZES, key=lambda edge: abs(edge - requested))


def _media_loader_thumbnail_key(path: str, max_edge: int) -> str:
    stat = os.stat(path)
    payload = f"{os.path.realpath(path)}|{stat.st_mtime_ns}|{stat.st_size}|{max_edge}"
    return hashlib.sha1(payload.encode("utf-8", "surrogateescape")).hexdigest()


def _media_loader_thumbnail_lock(key: str) -> Any:
    """Return a per-key lock so concurrent requests only decode the file once."""
    with _MEDIA_LOADER_THUMBNAIL_REGISTRY_LOCK:
        lock = _MEDIA_LOADER_THUMBNAIL_LOCKS.get(key)
        if lock is None:
            if len(_MEDIA_LOADER_THUMBNAIL_LOCKS) > 4096:
                _MEDIA_LOADER_THUMBNAIL_LOCKS.clear()
            lock = threading.Lock()
            _MEDIA_LOADER_THUMBNAIL_LOCKS[key] = lock
        return lock


def _media_loader_prune_thumbnails(cache_dir: str) -> None:
    """Drop expired entries and, when space runs low, the oldest files first."""
    now = time.time()
    try:
        usage = shutil.disk_usage(cache_dir)
    except OSError:
        usage = None
    low_space = bool(usage and usage.free < MEDIA_LOADER_THUMBNAIL_MIN_FREE_BYTES)
    entries: list[tuple[float, str]] = []
    try:
        for entry in os.scandir(cache_dir):
            if not entry.is_file() or not entry.name.endswith(".webp"):
                continue
            try:
                stat = entry.stat()
            except OSError:
                continue
            if low_space or now - stat.st_mtime > MEDIA_LOADER_THUMBNAIL_TTL:
                entries.append((stat.st_mtime, entry.path))
    except OSError:
        return
    if low_space:
        entries.sort()
    for _mtime, candidate in entries:
        try:
            os.remove(candidate)
        except OSError:
            continue


def _media_loader_encode_thumbnail(image: Any, target: str) -> None:
    if image.mode not in {"RGB", "RGBA"}:
        image = image.convert("RGBA" if image.mode in {"P", "LA", "PA"} else "RGB")
    temporary = f"{target}.{os.getpid()}.tmp"
    try:
        image.save(temporary, format="WEBP", quality=82, method=4)
        os.replace(temporary, target)
    except OSError:
        # A failed write must not leave a stray file behind for the next run.
        try:
            os.remove(temporary)
        except OSError:
            pass
        raise


def _media_loader_placeholder(label: str, max_edge: int, target: str) -> None:
    """Render a labelled fallback so the panel never shows a broken image."""
    from PIL import ImageDraw

    edge = max(64, int(max_edge))
    image = Image.new("RGB", (edge, edge), (38, 42, 47))
    draw = ImageDraw.Draw(image)
    text = str(label or "?")[:6].upper()
    left, top, right, bottom = draw.textbbox((0, 0), text)
    draw.text(((edge - right + left) / 2, (edge - bottom + top) / 2), text, fill=(190, 205, 220))
    _media_loader_encode_thumbnail(image, target)


def _media_loader_image_thumbnail(path: str, max_edge: int, target: str) -> None:
    suffix = os.path.splitext(path)[1].lower()
    keep_alpha = suffix in {".png", ".webp", ".gif", ".avif", ".tif", ".tiff"}
    try:
        with Image.open(path) as handle:
            # Ask JPEG decoders for a downscaled buffer before the full decode.
            handle.draft(None, (max_edge * 2, max_edge * 2))
            width, height = handle.size
            if width * height > MEDIA_LOADER_THUMBNAIL_MAX_PIXELS:
                raise ValueError("图片尺寸过大，无法生成缩略图")
            image = handle.convert("RGBA" if keep_alpha else "RGB")
    except Exception:
        # HEIC needs pillow-heif, which ComfyUI does not depend on.
        _media_loader_placeholder(suffix.lstrip("."), max_edge, target)
        return
    image.thumbnail((max_edge, max_edge), Image.LANCZOS)
    _media_loader_encode_thumbnail(image, target)


def _media_loader_video_thumbnail(path: str, max_edge: int, target: str) -> None:
    """Grab the first reasonably bright frame so the tile is not a black square."""
    image = None
    try:
        import av

        frame_count = 0
        with av.open(path) as container:
            streams = container.streams.video
            if not streams:
                raise ValueError("视频没有可用画面流")
            stream = streams[0]
            stream.thread_type = "AUTO"
            for frame in container.decode(stream):
                frame_count += 1
                candidate = frame.to_image().convert("RGB")
                candidate.thumbnail((max_edge, max_edge), Image.LANCZOS)
                image = candidate
                from PIL import ImageStat

                if float(ImageStat.Stat(candidate.convert("L")).mean[0]) >= 8.0 or frame_count >= 8:
                    break
    except Exception:
        image = None
    if image is None:
        _media_loader_placeholder("VID", max_edge, target)
        return
    _media_loader_encode_thumbnail(image, target)


def _media_loader_build_thumbnail(path: str, max_edge: int, target: str) -> None:
    if _media_loader_kind(path) == "video":
        _media_loader_video_thumbnail(path, max_edge, target)
    else:
        _media_loader_image_thumbnail(path, max_edge, target)


def _media_loader_get_thumbnail(filename: str, max_edge: int) -> str:
    """Return the cached webp path, generating it once per source revision."""
    global _MEDIA_LOADER_THUMBNAIL_LAST_PRUNE

    source = _media_loader_input_path(filename)
    if _media_loader_kind(source) not in {"image", "video"}:
        raise ValueError(f"不支持为该文件生成缩略图: {filename}")
    cache_dir = _media_loader_thumbnail_cache_dir()
    key = _media_loader_thumbnail_key(source, max_edge)
    target = os.path.join(cache_dir, f"{key}.webp")

    cache_key = (key, max_edge)
    if cache_key in _MEDIA_LOADER_THUMBNAIL_CACHE and os.path.isfile(target):
        return target

    lock = _media_loader_thumbnail_lock(key)
    with lock:
        if os.path.isfile(target):
            _MEDIA_LOADER_THUMBNAIL_CACHE[cache_key] = target
            return target
        now = time.monotonic()
        if now - _MEDIA_LOADER_THUMBNAIL_LAST_PRUNE > MEDIA_LOADER_THUMBNAIL_PRUNE_INTERVAL:
            _MEDIA_LOADER_THUMBNAIL_LAST_PRUNE = now
            try:
                _media_loader_prune_thumbnails(cache_dir)
            except Exception:
                pass
        _media_loader_build_thumbnail(source, max_edge, target)
        if len(_MEDIA_LOADER_THUMBNAIL_CACHE) > 8192:
            _MEDIA_LOADER_THUMBNAIL_CACHE.clear()
        _MEDIA_LOADER_THUMBNAIL_CACHE[cache_key] = target
    return target


def _register_media_loader_routes() -> None:
    """Expose a safe, non-recursive input-folder browser to the frontend."""
    try:
        from aiohttp import web
        from server import PromptServer
    except Exception:
        return
    server = getattr(PromptServer, "instance", None)
    if server is None or getattr(server, "_wysl_media_loader_routes", False):
        return

    @server.routes.get("/wysl/media-loader/list")
    async def wysl_media_loader_list(request):
        try:
            folder = str(request.query.get("folder", ""))
            current, directories, files = _media_loader_list_folder(folder)
            parent = "/".join(current.split("/")[:-1]) if current else ""
            return web.json_response({
                "folder": current,
                "parent": parent,
                "directories": directories,
                "files": files,
            })
        except ValueError as exc:
            return web.json_response({"error": str(exc)}, status=400)
        except OSError as exc:
            return web.json_response({"error": f"无法读取 input 文件夹: {exc}"}, status=500)

    @server.routes.get("/wysl/media-loader/thumbnail")
    async def wysl_media_loader_thumbnail(request):
        filename = str(request.query.get("filename", ""))
        max_edge = _media_loader_thumbnail_max_edge(request.query.get("size"))
        try:
            loop = asyncio.get_running_loop()
            # Decoding images and video blocks, so keep it off the server event
            # loop while the panel requests many tiles at once.
            thumb_path = await loop.run_in_executor(
                _media_loader_thumbnail_executor(),
                _media_loader_get_thumbnail,
                filename,
                max_edge,
            )
        except ValueError as exc:
            return web.json_response({"error": str(exc)}, status=404)
        except OSError as exc:
            return web.json_response({"error": f"无法生成缩略图: {exc}"}, status=500)
        return web.FileResponse(
            thumb_path,
            headers={
                "Content-Type": "image/webp",
                # Short enough that a replaced source file is picked up again,
                # long enough that re-opening the panel stays instant.
                "Cache-Control": "public, max-age=3600",
                "X-Content-Type-Options": "nosniff",
            },
        )

    server._wysl_media_loader_routes = True


_register_media_loader_routes()


def _bundle_items(media_bundle: Any) -> list[Any]:
    """Read the native H3 bundle and a small mapping-based compatibility shape."""
    items = getattr(media_bundle, "items", None)
    if items is not None and not callable(items):
        return list(items)
    if isinstance(media_bundle, Mapping):
        raw_items = media_bundle.get("items")
        if isinstance(raw_items, (list, tuple)):
            return list(raw_items)
        result: list[Any] = []
        for kind in ("image", "audio", "video"):
            values = media_bundle.get(f"{kind}s", media_bundle.get(kind, []))
            if values is None:
                continue
            if not isinstance(values, (list, tuple)):
                values = [values]
            result.extend({"media_type": kind, "value": value} for value in values)
        return result
    raise ValueError("请连接 MiniMax H3 Easy 媒体加载器输出的媒体包")


def _item_parts(item: Any) -> tuple[str, Any] | None:
    if isinstance(item, Mapping):
        media_type = item.get("media_type", item.get("type", item.get("kind")))
        value = item.get("value", item.get("data", item.get("media")))
    else:
        media_type = getattr(item, "media_type", getattr(item, "type", getattr(item, "kind", None)))
        value = getattr(item, "value", getattr(item, "data", getattr(item, "media", None)))
        if media_type is None and isinstance(item, (list, tuple)) and len(item) >= 2:
            media_type = item[-2]
            value = item[-1]

    normalized = str(media_type or "").strip().lower()
    aliases = {
        "image": "image",
        "images": "image",
        "img": "image",
        "picture": "image",
        "audio": "audio",
        "audios": "audio",
        "sound": "audio",
        "video": "video",
        "videos": "video",
        "movie": "video",
    }
    kind = aliases.get(normalized)
    return (kind, value) if kind is not None else None


def _image_values(value: Any) -> list[torch.Tensor]:
    """Flatten IMAGE batches while retaining a one-image batch per output item."""
    if isinstance(value, torch.Tensor):
        if value.ndim == 4:
            return [value[index : index + 1] for index in range(int(value.shape[0]))]
        if value.ndim == 3:
            return [value.unsqueeze(0)]
        raise ValueError("媒体包中的图像必须是 HWC 或 BHWC 张量")
    if isinstance(value, (list, tuple)):
        result: list[torch.Tensor] = []
        for item in value:
            result.extend(_image_values(item))
        return result
    raise ValueError("媒体包包含无法识别的图像数据")


def _audio_values(value: Any) -> list[Any]:
    if isinstance(value, (list, tuple)):
        result: list[Any] = []
        for item in value:
            result.extend(_audio_values(item))
        return result
    if isinstance(value, Mapping) and isinstance(value.get("waveform"), torch.Tensor):
        return [value]
    raise ValueError("媒体包中的音频必须包含 waveform")


def _video_values(value: Any) -> list[Any]:
    if isinstance(value, (list, tuple)):
        result: list[Any] = []
        for item in value:
            result.extend(_video_values(item))
        return result
    return [_standard_video(value)]


def _standard_video(value: Any) -> Any:
    """Convert the H3 loader's cached mapping into ComfyUI's VIDEO value."""
    if hasattr(value, "get_components"):
        return value
    if not isinstance(value, Mapping):
        raise ValueError("媒体包中的视频格式无法识别")

    nested = value.get("video")
    if nested is not None and nested is not value:
        return _standard_video(nested)

    frames = value.get("images", value.get("frames"))
    if not isinstance(frames, torch.Tensor) or frames.ndim != 4 or frames.shape[0] < 1:
        raise ValueError("媒体包中的视频没有有效帧")
    fps = value.get("fps", value.get("frame_rate", 24.0)) or 24.0
    try:
        frame_rate = Fraction(str(float(fps)))
    except (TypeError, ValueError) as exc:
        raise ValueError("媒体包中的视频 FPS 无效") from exc

    audio = value.get("audio")
    audio_payload = None
    if isinstance(audio, Mapping) and isinstance(audio.get("waveform"), torch.Tensor):
        audio_payload = audio
    components = make_video_components(
        frames,
        audio=audio_payload,
        frame_rate=frame_rate,
        metadata=value.get("metadata"),
        alpha=value.get("alpha"),
    )
    try:
        from comfy_api.latest import InputImpl

        return InputImpl.VideoFromComponents(components)
    except TypeError as exc:
        # Older VIDEO APIs may reject metadata or alpha even after the helper's
        # component fallback. Retry with the smallest valid component payload.
        if "metadata" in str(exc) or "alpha" in str(exc):
            components = make_video_components(
                frames,
                audio=audio_payload,
                frame_rate=frame_rate,
            )
            return InputImpl.VideoFromComponents(components)
        raise


def _normalize_image(image: torch.Tensor, *, max_edge: int) -> torch.Tensor:
    image = image[:1]
    if image.ndim != 4 or image.shape[0] != 1:
        raise ValueError("图像批次形状必须是 [1,H,W,C]")
    if image.shape[-1] == 1:
        image = image.repeat(1, 1, 1, 3)
    elif image.shape[-1] >= 3:
        image = image[..., :3]
    else:
        raise ValueError("图像必须至少包含一个颜色通道")
    if not torch.is_floating_point(image):
        image = image.float()
        if float(image.max().item()) > 1.0:
            image = image / 255.0
    image = image.clamp(0.0, 1.0)

    height, width = int(image.shape[1]), int(image.shape[2])
    longest = max(height, width)
    if longest <= max_edge:
        return image
    scale = max_edge / float(longest)
    target_height = max(1, int(round(height * scale)))
    target_width = max(1, int(round(width * scale)))
    image = torch.nn.functional.interpolate(
        image.permute(0, 3, 1, 2),
        size=(target_height, target_width),
        mode="bilinear",
        align_corners=False,
    )
    return image.permute(0, 2, 3, 1).contiguous()


MEDIA_COMPOSE_LAYOUTS = ("从左向右", "从右向左", "单元居中排列")
MEDIA_COMPOSE_GAP = 10


def _media_compose_scalar(value: Any, default: Any) -> Any:
    """Unwrap ComfyUI's widget transport list for INPUT_IS_LIST nodes."""
    while isinstance(value, (list, tuple)):
        if not value:
            return default
        value = value[0]
    return default if value is None else value


def _media_compose_bundle(value: Any) -> Any:
    """Unwrap the one-item MEDIA_BUNDLE transport list, if present."""
    if isinstance(value, (list, tuple)) and not value:
        return None
    if isinstance(value, (list, tuple)) and len(value) == 1:
        return value[0]
    return value


def _compose_images(
    images: list[torch.Tensor],
    max_edge: int = 1024,
    layout: str = "从左向右",
) -> torch.Tensor | None:
    if not images:
        return None
    max_edge = max(64, min(int(max_edge), 4096))
    normalized = [_normalize_image(image, max_edge=max_edge) for image in images]
    cell_height = max(int(image.shape[1]) for image in normalized)
    cell_width = max(int(image.shape[2]) for image in normalized)
    if layout in ("从左向右", "从右向左"):
        # Directional modes are a single horizontal strip. The previous
        # implementation only mirrored an automatically sized grid, so four
        # images still became a 2x2 layout instead of one row.
        columns = len(normalized)
        rows = 1
    else:
        columns = max(1, int(math.ceil(math.sqrt(len(normalized)))))
        rows = int(math.ceil(len(normalized) / columns))
    first = normalized[0]
    gap = MEDIA_COMPOSE_GAP
    if layout in ("从左向右", "从右向左"):
        # Directional strips use each image's own width. This keeps the
        # separator exactly 10px even when source images have different
        # aspect ratios, instead of introducing extra cell padding.
        ordered = normalized if layout == "从左向右" else list(reversed(normalized))
        canvas = torch.zeros(
            (
                1,
                cell_height,
                sum(int(image.shape[2]) for image in ordered) + max(0, len(ordered) - 1) * gap,
                3,
            ),
            dtype=first.dtype,
            device=first.device,
        )
        left = 0
        for image in ordered:
            height, width = int(image.shape[1]), int(image.shape[2])
            canvas[:, :height, left : left + width, :] = image.to(
                device=canvas.device,
                dtype=canvas.dtype,
            )
            left += width + gap
        return canvas

    canvas = torch.zeros(
        (
            1,
            rows * cell_height + max(0, rows - 1) * gap,
            columns * cell_width + max(0, columns - 1) * gap,
            3,
        ),
        dtype=first.dtype,
        device=first.device,
    )
    for index, image in enumerate(normalized):
        row, column = divmod(index, columns)
        height, width = int(image.shape[1]), int(image.shape[2])
        if layout == "单元居中排列":
            top = row * (cell_height + gap) + (cell_height - height) // 2
            left = column * (cell_width + gap) + (cell_width - width) // 2
        else:
            top = row * (cell_height + gap)
            left = column * (cell_width + gap)
        canvas[:, top : top + height, left : left + width, :] = image.to(
            device=canvas.device,
            dtype=canvas.dtype,
        )
    return canvas


class WyslMediaAutoSplitter:
    """Split a mixed H3 media bundle and optionally compose its images."""

    CATEGORY = "Wysl/工具"
    FUNCTION = "split"
    RETURN_TYPES = ("IMAGE", "AUDIO", "VIDEO", "IMAGE")
    RETURN_NAMES = ("图像", "音频", "视频", "图片组合")
    OUTPUT_IS_LIST = (True, True, True, False)
    # Wysl-多媒体加载的 multi output 是 ComfyUI 列表输出。没有这一项时，
    # ComfyUI 会对列表中的每张图分别调用 split()，导致“图片组合”变成多张
    # 单图，而不是一张保留所有横竖比例的组合图。
    INPUT_IS_LIST = True
    DESCRIPTION = (
        "自动识别媒体包或图片列表中的图像、音频和视频；前三个输出保留输入顺序，"
        "图片组合会一次保留全部图片的原始宽高比并拼接为一张图。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "optional": {
                "media_bundle": (MEDIA_BUNDLE_TYPE,),
                "image": ("IMAGE",),
                "组合图片长边": (
                    "INT",
                    {
                        "default": 1024,
                        "min": 64,
                        "max": 4096,
                        "step": 64,
                        "tooltip": "仅影响图片组合输出；图像列表输出保持原始分辨率。",
                    },
                ),
                "组合排列": (
                    list(MEDIA_COMPOSE_LAYOUTS),
                    {
                        "default": "从左向右",
                        "tooltip": "控制图片在自动网格中的排列方向和单元对齐方式。",
                    },
                ),
            }
        }

    @staticmethod
    def split(media_bundle=None, image=None, 组合图片长边=1024, 组合排列="从左向右"):
        images: list[torch.Tensor] = []
        audios: list[Any] = []
        videos: list[Any] = []
        media_bundle = _media_compose_bundle(media_bundle)
        if media_bundle is not None:
            bundle_items = _bundle_items(media_bundle)
            for item in bundle_items:
                parts = _item_parts(item)
                if parts is None:
                    continue
                kind, value = parts
                if kind == "image":
                    images.extend(_image_values(value))
                elif kind == "audio":
                    audios.extend(_audio_values(value))
                elif kind == "video":
                    videos.extend(_video_values(value))
        elif image is not None:
            images.extend(_image_values(image))

        image_output = images if images else _execution_blocker()
        audio_output = audios if audios else _execution_blocker()
        video_output = videos if videos else _execution_blocker()
        combined = _compose_images(
            images,
            int(_media_compose_scalar(组合图片长边, 1024)),
            str(_media_compose_scalar(组合排列, "从左向右")),
        )
        combined_output = combined if combined is not None else _execution_blocker()
        return image_output, audio_output, video_output, combined_output


class WyslMediaLoader:
    """Load media into separate lists and the upstream-compatible media bundle."""

    CATEGORY = "Wysl/工具"
    FUNCTION = "load"
    RETURN_TYPES = ("IMAGE", "AUDIO", "VIDEO", MEDIA_BUNDLE_TYPE)
    RETURN_NAMES = ("multi output", "audio output", "video output", "media_bundle")
    OUTPUT_IS_LIST = (True, True, True, False)
    DESCRIPTION = (
        "从 ComfyUI/input 中按选择顺序加载图片、音频和视频；"
        "三种媒体分别输出，不会混合。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "media_state": (
                    "STRING",
                    {
                        "default": "",
                        "multiline": False,
                    },
                ),
            }
        }

    @classmethod
    def IS_CHANGED(cls, media_state="", **_kwargs):
        state = _media_loader_normalize_state(media_state)
        signature: list[tuple[str, str, int | None, int | None]] = []
        for kind in ("images", "audios", "videos"):
            for filename in state[kind]:
                try:
                    stat = os.stat(_media_loader_input_path(filename))
                    signature.append((kind, filename, stat.st_mtime_ns, stat.st_size))
                except (OSError, ValueError):
                    signature.append((kind, filename, None, None))
        return repr(signature)

    @classmethod
    def VALIDATE_INPUTS(cls, media_state="", **_kwargs):
        state = _media_loader_normalize_state(media_state)
        for kind in ("images", "audios", "videos"):
            for filename in state[kind]:
                try:
                    _media_loader_input_path(filename)
                except ValueError as exc:
                    return str(exc)
        return True

    def load(self, media_state=""):
        state = _media_loader_normalize_state(media_state)
        images: list[torch.Tensor] = []
        audios: list[dict[str, Any]] = []
        videos: list[Any] = []
        bundle_items: list[WyslMediaInput] = []
        input_index = 0
        for filename in state["images"]:
            _media_loader_input_path(filename)
            value = _media_loader_load_image(filename)
            images.append(value)
            input_index += 1
            bundle_items.append(WyslMediaInput(input_index, "image", value))
        for filename in state["audios"]:
            value = _media_loader_load_audio(_media_loader_input_path(filename))
            audios.append(value)
            input_index += 1
            bundle_items.append(WyslMediaInput(input_index, "audio", value))
        for filename in state["videos"]:
            value = _standard_video(_media_loader_load_video(_media_loader_input_path(filename)))
            videos.append(value)
            input_index += 1
            bundle_items.append(WyslMediaInput(input_index, "video", value))
        return images, audios, videos, WyslMediaBundle(tuple(bundle_items))


MEDIA_INDEX_MAX_OUTPUTS = 64

MEDIA_INDEX_ASPECT_RATIOS = ("原图", "自定义", "1:1", "3:2", "4:3", "16:9", "2:3", "3:4", "9:16")
MEDIA_INDEX_FIT_MODES = ("留白", "裁剪", "拉伸")
MEDIA_INDEX_METHODS = ("lanczos", "bicubic", "hamming", "bilinear", "box", "nearest")
MEDIA_INDEX_MULTIPLES = ("8", "16", "32", "64", "128", "256", "512", "不对齐")
MEDIA_INDEX_SCALE_SIDES = ("不缩放", "长边", "短边", "宽度", "高度", "总像素(万像素)")
MEDIA_INDEX_LEGACY_TOTAL_PIXELS = "总像素(kilo pixel)"


def _media_index_image_values(value: Any) -> list[Any]:
    """Split an IMAGE batch into one output value per image."""
    if isinstance(value, torch.Tensor):
        if value.ndim == 4:
            return [value[index : index + 1] for index in range(int(value.shape[0]))]
        if value.ndim == 3:
            return [value.unsqueeze(0)]
    if isinstance(value, (list, tuple)):
        result: list[Any] = []
        for item in value:
            result.extend(_media_index_image_values(item))
        return result
    return [value]


def _media_index_add_item(result: list[tuple[str, Any]], kind: str, value: Any) -> None:
    if kind == "image":
        result.extend((kind, image) for image in _media_index_image_values(value))
    else:
        result.append((kind, value))


def _media_index_items(value: Any) -> list[tuple[str, Any]]:
    """Normalize an IMAGE list or H3 media bundle into typed output values."""
    # ComfyUI wraps a non-list output in a one-item list before invoking a
    # node with INPUT_IS_LIST=True. Unwrap that transport wrapper so a
    # media_bundle is split by its contained items instead of being emitted as
    # one opaque value.
    if isinstance(value, (list, tuple)) and len(value) == 1:
        candidate = value[0]
        if isinstance(candidate, WyslMediaBundle) or (
            getattr(candidate, "items", None) is not None
            and not callable(getattr(candidate, "items", None))
        ):
            return _media_index_items(candidate)
        if isinstance(candidate, Mapping) and (
            "items" in candidate
            or any(key in candidate for key in ("images", "audios", "videos", "image", "audio", "video"))
        ):
            return _media_index_items(candidate)
    if isinstance(value, WyslMediaBundle) or (
        getattr(value, "items", None) is not None
        and not callable(getattr(value, "items", None))
    ):
        raw_items = value.items
    elif isinstance(value, Mapping):
        raw_items = _bundle_items(value)
    elif isinstance(value, (list, tuple)):
        # A list from the loader's multi output is an ordered IMAGE list. The
        # individual tensor type is already known by the connected source.
        result: list[tuple[str, Any]] = []
        for item in value:
            _media_index_add_item(result, "image", item)
        return result
    elif value is None:
        return []
    else:
        return [("image", value)]

    result = []
    for item in raw_items:
        parts = _item_parts(item)
        if parts is None:
            continue
        _media_index_add_item(result, *parts)
    return result


def _media_index_target_size(
    width: int,
    height: int,
    aspect_ratio: str,
    proportional_width: int,
    proportional_height: int,
    scale_to_side: str,
    scale_to_length: int,
    round_to_multiple: str,
) -> tuple[int, int]:
    """Match LayerStyle ImageScaleByAspectRatio V2 target-size rules."""
    if aspect_ratio == "原图":
        ratio = width / max(height, 1)
    elif aspect_ratio == "自定义":
        ratio = max(int(proportional_width), 1) / max(int(proportional_height), 1)
    else:
        numerator, denominator = aspect_ratio.split(":", 1)
        ratio = int(numerator) / int(denominator)

    scale_to_length = max(int(scale_to_length), 4)
    if ratio > 1:
        if scale_to_side == "长边":
            target_width, target_height = scale_to_length, int(scale_to_length / ratio)
        elif scale_to_side == "短边":
            target_height, target_width = scale_to_length, int(scale_to_length * ratio)
        elif scale_to_side == "宽度":
            target_width, target_height = scale_to_length, int(scale_to_length / ratio)
        elif scale_to_side == "高度":
            target_height, target_width = scale_to_length, int(scale_to_length * ratio)
        elif scale_to_side in ("总像素(万像素)", MEDIA_INDEX_LEGACY_TOTAL_PIXELS):
            pixel_unit = 10000 if scale_to_side == "总像素(万像素)" else 1000
            target_width = int(math.sqrt(ratio * scale_to_length * pixel_unit))
            target_height = int(target_width / ratio)
        else:
            target_width, target_height = width, int(width / ratio)
    else:
        if scale_to_side == "长边":
            target_height, target_width = scale_to_length, int(scale_to_length * ratio)
        elif scale_to_side == "短边":
            target_width, target_height = scale_to_length, int(scale_to_length / ratio)
        elif scale_to_side == "宽度":
            target_width, target_height = scale_to_length, int(scale_to_length / ratio)
        elif scale_to_side == "高度":
            target_height, target_width = scale_to_length, int(scale_to_length * ratio)
        elif scale_to_side in ("总像素(万像素)", MEDIA_INDEX_LEGACY_TOTAL_PIXELS):
            pixel_unit = 10000 if scale_to_side == "总像素(万像素)" else 1000
            target_width = int(math.sqrt(ratio * scale_to_length * pixel_unit))
            target_height = int(target_width / ratio)
        else:
            target_height, target_width = height, int(height * ratio)

    target_width = max(int(target_width), 1)
    target_height = max(int(target_height), 1)
    if round_to_multiple != "不对齐":
        multiple = max(int(round_to_multiple), 1)
        target_width = ((target_width + multiple - 1) // multiple) * multiple
        target_height = ((target_height + multiple - 1) // multiple) * multiple
    return target_width, target_height


def _media_index_tensor_to_pil(value: Any) -> Image.Image:
    import numpy as np

    if not isinstance(value, torch.Tensor):
        raise ValueError("图片输出必须是 IMAGE 张量")
    image = value.detach().to(device="cpu")
    if image.ndim == 4:
        image = image[0]
    if image.ndim != 3:
        raise ValueError("图片输出必须是 HWC 或 BHWC 张量")
    image = image.float()
    if float(image.max().item()) > 1.0:
        image = image / 255.0
    image = image.clamp(0.0, 1.0).mul(255.0).round().to(torch.uint8).numpy()
    if image.shape[-1] == 4:
        return Image.fromarray(image, mode="RGBA").convert("RGB")
    if image.shape[-1] == 1:
        return Image.fromarray(image[:, :, 0], mode="L").convert("RGB")
    return Image.fromarray(image[:, :, :3], mode="RGB")


def _media_index_pil_to_tensor(image: Image.Image) -> torch.Tensor:
    import numpy as np

    array = np.asarray(image.convert("RGB"), dtype=np.float32) / 255.0
    return torch.from_numpy(array).unsqueeze(0).contiguous()


def _media_index_resize_image(
    value: Any,
    target_width: int,
    target_height: int,
    fit: str,
    method: str,
    background_color: str,
) -> Any:
    image = _media_index_tensor_to_pil(value)
    resampling = getattr(Image, "Resampling", Image)
    sampler = {
        "lanczos": resampling.LANCZOS,
        "bicubic": resampling.BICUBIC,
        "hamming": resampling.HAMMING,
        "bilinear": resampling.BILINEAR,
        "box": resampling.BOX,
        "nearest": resampling.NEAREST,
    }.get(str(method), resampling.LANCZOS)
    target_size = (int(target_width), int(target_height))
    image_width, image_height = image.size
    if fit == "留白":
        if image_width / max(image_height, 1) > target_width / max(target_height, 1):
            fit_width = target_width
            fit_height = max(1, int(target_width / max(image_width, 1) * image_height))
        else:
            fit_height = target_height
            fit_width = max(1, int(target_height / max(image_height, 1) * image_width))
        fitted = image.resize((fit_width, fit_height), sampler)
        try:
            fill = ImageColor.getrgb(str(background_color))
        except (TypeError, ValueError):
            fill = (0, 0, 0)
        output = Image.new("RGB", target_size, color=fill)
        output.paste(fitted, ((target_width - fit_width) // 2, (target_height - fit_height) // 2))
        return _media_index_pil_to_tensor(output)
    if fit == "裁剪":
        if image_width / max(image_height, 1) > target_width / max(target_height, 1):
            fit_width = max(1, int(image_height * target_width / max(target_height, 1)))
            left = max(0, (image_width - fit_width) // 2)
            image = image.crop((left, 0, left + fit_width, image_height))
        else:
            fit_height = max(1, int(image_width * target_height / max(target_width, 1)))
            top = max(0, (image_height - fit_height) // 2)
            image = image.crop((0, top, image_width, top + fit_height))
    return _media_index_pil_to_tensor(image.resize(target_size, sampler))


def _media_index_scale_items(
    items: list[tuple[str, Any]],
    scale_mode: str,
    aspect_ratio: str,
    proportional_width: int,
    proportional_height: int,
    fit: str,
    method: str,
    round_to_multiple: str,
    scale_to_side: str,
    scale_to_length: int,
    background_color: str,
) -> list[tuple[str, Any]]:
    if scale_mode == "关闭":
        return items
    scaled: list[tuple[str, Any]] = []
    for kind, value in items:
        if kind == "image":
            if not isinstance(value, torch.Tensor):
                scaled.append((kind, value))
                continue
            image = value[0] if value.ndim == 4 else value
            if image.ndim != 3:
                scaled.append((kind, value))
                continue
            # "原图" must be resolved independently for every image. A
            # mixed batch can contain portrait and landscape frames, so using
            # the first image's dimensions would force the rest into a shared
            # canvas and introduce unintended padding.
            height, width = int(image.shape[0]), int(image.shape[1])
            target_width, target_height = _media_index_target_size(
                width,
                height,
                aspect_ratio,
                proportional_width,
                proportional_height,
                scale_to_side,
                scale_to_length,
                round_to_multiple,
            )
            value = _media_index_resize_image(
                value,
                target_width,
                target_height,
                fit,
                method,
                background_color,
            )
        scaled.append((kind, value))
    return scaled


def _media_index_scalar(value: Any, default: Any) -> Any:
    """Unwrap ComfyUI's one-item lists used by INPUT_IS_LIST widgets."""
    while isinstance(value, (list, tuple)):
        if not value:
            return default
        value = value[0]
    return default if value is None else value


class WyslMediaIndexOutput:
    """Split an ordered media list/bundle into individually addressable ports."""

    CATEGORY = "Wysl/工具"
    FUNCTION = "split"
    INPUT_IS_LIST = True
    RETURN_TYPES = ("*",) * MEDIA_INDEX_MAX_OUTPUTS
    RETURN_NAMES = tuple(f"媒体 {index}" for index in range(1, MEDIA_INDEX_MAX_OUTPUTS + 1))
    OUTPUT_IS_LIST = (False,) * MEDIA_INDEX_MAX_OUTPUTS
    DESCRIPTION = (
        "按输入顺序将图片、音频或视频列表拆成独立输出；"
        "前端会根据连接的 Wysl 多媒体加载器自动显示实际端口。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "media": ("*", {"forceInput": True}),
                "缩放模式": (["关闭", "按宽高比缩放"], {"default": "关闭"}),
                "宽高比": (MEDIA_INDEX_ASPECT_RATIOS, {"default": "原图"}),
                "自定义宽度": ("INT", {"default": 1, "min": 1, "max": 100000000, "step": 1}),
                "自定义高度": ("INT", {"default": 1, "min": 1, "max": 100000000, "step": 1}),
                "适配方式": (MEDIA_INDEX_FIT_MODES, {"default": "留白"}),
                "缩放算法": (MEDIA_INDEX_METHODS, {"default": "lanczos"}),
                "对齐倍数": (MEDIA_INDEX_MULTIPLES, {"default": "不对齐"}),
                "缩放基准": (MEDIA_INDEX_SCALE_SIDES, {"default": "不缩放"}),
                "缩放长度": ("INT", {"default": 1024, "min": 4, "max": 100000000, "step": 1}),
                "背景颜色": ("STRING", {"default": "#000000", "multiline": False}),
            }
        }

    @staticmethod
    def split(
        media=None,
        缩放模式="关闭",
        宽高比="原图",
        自定义宽度=1,
        自定义高度=1,
        适配方式="留白",
        缩放算法="lanczos",
        对齐倍数="不对齐",
        缩放基准="不缩放",
        缩放长度=1024,
        背景颜色="#000000",
        **_kwargs,
    ):
        items = _media_index_scale_items(
            _media_index_items(media),
            str(_media_index_scalar(缩放模式, "关闭")),
            str(_media_index_scalar(宽高比, "原图")),
            int(_media_index_scalar(自定义宽度, 1)),
            int(_media_index_scalar(自定义高度, 1)),
            str(_media_index_scalar(适配方式, "留白")),
            str(_media_index_scalar(缩放算法, "lanczos")),
            str(_media_index_scalar(对齐倍数, "不对齐")),
            str(_media_index_scalar(缩放基准, "不缩放")),
            int(_media_index_scalar(缩放长度, 1024)),
            str(_media_index_scalar(背景颜色, "#000000")),
        )
        outputs: list[Any] = [None] * MEDIA_INDEX_MAX_OUTPUTS
        for index, (_kind, value) in enumerate(items):
            if index >= MEDIA_INDEX_MAX_OUTPUTS:
                break
            outputs[index] = value
        return tuple(outputs)


